previewCss:
.darma-loader-darma-b14-console-faders { --accent: var(--loader-color, #22d3ee); --accent-2: var(--loader-secondary-color, #f43f5e); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .82); display: flex; justify-content: space-between; padding: 8% 7%; border-radius: 5px; background: linear-gradient(#334155, #0b1220); box-shadow: inset 0 0 0 2px #475569; }
.darma-loader-darma-b14-console-faders span { position: relative; width: 11%; border-radius: 999px; background: rgba(255, 255, 255, .12); }
.darma-loader-darma-b14-console-faders span::before { content: ''; position: absolute; top: -7%; left: 8%; width: 84%; height: 5%; border-radius: 999px; background: var(--accent-2); animation: darma-loader-darma-b14-console-faders-led calc(var(--loader-speed, 1s) * 1.1) steps(2, end) infinite; }
.darma-loader-darma-b14-console-faders span::after { content: ''; position: absolute; left: -32%; width: 164%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); box-shadow: 0 2px 4px rgba(0, 0, 0, .45); animation: darma-loader-darma-b14-console-faders-fade-move calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b14-console-faders span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b14-console-faders span:nth-child(2)::before { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b14-console-faders span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b14-console-faders span:nth-child(3)::before { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b14-console-faders span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b14-console-faders span:nth-child(4)::before { animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b14-console-faders span:nth-child(5)::after { animation-delay: calc(var(--loader-speed, 1s) * .72); }
.darma-loader-darma-b14-console-faders span:nth-child(5)::before { animation-delay: calc(var(--loader-speed, 1s) * .72); }
@keyframes darma-loader-darma-b14-console-faders-fade-move { 0%, 100% { top: 6%; } 50% { top: 78%; } }
@keyframes darma-loader-darma-b14-console-faders-led { 0%, 100% { opacity: .28; } 50% { opacity: 1; } }

